@@ -14,25 +16,45 @@ public final class ZipUtils {

     private ZipUtils() {}

+    /**
+     * Validates that the destination file for a zip entry resolves to a path that is
+     * within the intended output directory, preventing path traversal ("Zip Slip") attacks.
+     */
+    private static File resolveDestinationFile(File outputDir, ZipEntry entry) throws IOException {
+        File destFile = new File(outputDir, entry.getName());
+
+        String destDirPath = outputDir.getCanonicalPath();
+        String destFilePath = destFile.getCanonicalPath();
+
+        if (!destFilePath.startsWith(destDirPath + File.separator) && !destFilePath.equals(destDirPath)) {
+            throw new IOException("Entry is outside of the target dir: " + entry.getName());
+        }
+
+        return destFile;
+    }
+
     public static void unzip(String zipFilePath, String destDir) throws java.io.IOException {
         File dir = new File(destDir);
         if (!dir.exists()) {
             dir.mkdirs();
         }

         try (ZipFile zipFile = new ZipFile(zipFilePath)) {
             Enumeration<? extends ZipEntry> entries = zipFile.entries();
             while (entries.hasMoreElements()) {
                 ZipEntry entry = entries.nextElement();
-                File entryDestination = new File(dir, entry.getName());
+                File entryDestination = resolveDestinationFile(dir, entry);
+
                 if (entry.isDirectory()) {
                     entryDestination.mkdirs();
                 } else {
                     entryDestination.getParentFile().mkdirs();
                     try (InputStream in = zipFile.getInputStream(entry);
                             OutputStream out = new FileOutputStream(entryDestination)) {
                         byte[] buffer = new byte[8192];
                         int len;
                         while ((len = in.read(buffer)) > 0) {
                             out.write(buffer, 0, len);
                         }
                     }
                 }
             }
         }
     }
 }

